// Regenerates components/library/previews.tsx from the files in demos/.
// Run after adding a component:  node scripts/gen-previews.mjs
import { readdirSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "components", "library");
const slugs = readdirSync(join(root, "demos"))
  .filter((f) => f.endsWith(".tsx"))
  .map((f) => f.replace(/\.tsx$/, ""))
  .sort();

const out = `"use client";

/* AUTO-GENERATED by scripts/gen-previews.mjs — do not edit by hand. */
import dynamic from "next/dynamic";
import type { ComponentType } from "react";

const loading = () => <div className="size-8 animate-pulse rounded-full bg-neutral-200 dark:bg-neutral-800" />;

export const previews: Record<string, ComponentType> = {
${slugs.map((s) => `  "${s}": dynamic(() => import("./demos/${s}"), { ssr: false, loading }),`).join("\n")}
};
`;

writeFileSync(join(root, "previews.tsx"), out);
console.log(`Wrote ${slugs.length} previews`);
